package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.*;import com.casystem.onboarding.repository.*;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.junit.jupiter.api.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PasswordRecoveryControllerTest{UserRepository users;PasswordResetTokenRepository resets;PasswordEncoder enc;AuditService audit;MailService mail;HttpServletRequest req;PasswordRecoveryController c;@BeforeEach void set(){users=mock(UserRepository.class);resets=mock(PasswordResetTokenRepository.class);enc=mock(PasswordEncoder.class);audit=mock(AuditService.class);mail=mock(MailService.class);req=mock(HttpServletRequest.class);when(req.getRemoteAddr()).thenReturn("127.0.0.1");c=new PasswordRecoveryController(users,resets,enc,audit,mail);}
 @Test void forgotRequiereEmail(){assertEquals(400,c.forgot(Map.of("email",""),req).getStatusCode().value());}
 @Test void forgotNoRevelaUsuarioInexistente(){when(users.findByEmailAndDeletedFalse("none@x.com")).thenReturn(Optional.empty());assertEquals(200,c.forgot(Map.of("email","none@x.com"),req).getStatusCode().value());verifyNoInteractions(mail);}
 @Test void forgotEnviaCorreo(){User u=user();when(users.findByEmailAndDeletedFalse("a@b.com")).thenReturn(Optional.of(u));assertEquals(200,c.forgot(Map.of("email"," A@B.COM "),req).getStatusCode().value());verify(resets).save(any(PasswordResetToken.class));verify(mail).recovery(eq("a@b.com"),anyString());verify(audit).log(3L,"RECUPERACION_EMAIL_ENVIADA","127.0.0.1");}
 @Test void forgotRevierteTokenSiFallaSmtp(){User u=user();when(users.findByEmailAndDeletedFalse("a@b.com")).thenReturn(Optional.of(u));doThrow(new IllegalStateException("smtp")).when(mail).recovery(eq("a@b.com"),anyString());assertEquals(503,c.forgot(Map.of("email","a@b.com"),req).getStatusCode().value());verify(resets).delete(any(PasswordResetToken.class));verify(audit).log(3L,"RECUPERACION_EMAIL_FALLIDA","127.0.0.1");}
 @Test void resetValidaPassword(){assertEquals(400,c.reset(Map.of("token","t","password","abc"),req).getStatusCode().value());}
 @Test void resetRechazaToken(){when(resets.findByTokenAndUsedFalse("bad")).thenReturn(Optional.empty());assertEquals(400,c.reset(Map.of("token","bad","password","Nueva123"),req).getStatusCode().value());}
 @Test void resetActualizaPassword(){User u=user();PasswordResetToken r=new PasswordResetToken();r.setUserId(3L);r.setToken("ok");r.setUsed(false);r.setExpiresAt(LocalDateTime.now().plusMinutes(5));when(resets.findByTokenAndUsedFalse("ok")).thenReturn(Optional.of(r));when(users.findById(3L)).thenReturn(Optional.of(u));when(enc.encode("Nueva123")).thenReturn("nuevohash");assertEquals(200,c.reset(Map.of("token","ok","password","Nueva123"),req).getStatusCode().value());assertEquals("nuevohash",u.getPassword());assertTrue(r.isUsed());verify(users).save(u);verify(resets).save(r);verify(audit).log(3L,"CONTRASENA_RESTABLECIDA","127.0.0.1");}
 private User user(){User u=new User();u.setId(3L);u.setEmail("a@b.com");u.setPassword("old");return u;}}
